  "dbdump.saveHint": "Kirjutab tõmmise failina valitud kausta serveris, omanikuks nobody:users, et saaksid selle võrgujagamise kaudu avada. Fail sisaldab kõiki tabeleid ja andmebaasi kasutajate paroolide räsisid; hoia seda kohas, kuhu pääsed ainult sina.",
  "dbdump.saveCancelHint": "Katkestamine peatab salvestamise ja eemaldab poolelioleva faili.",
  "dbdump.savedTo": "Salvestatud asukohta {path}",
  "dbdump.import": "Impordi värskesse andmebaasi",
  "dbdump.importConfirm": "Kas importida see {engine} {version} tõmmis konteinerisse {container}? BombVault peatab konteineri, lükkab selle andmekausta kõrvale (see jääb alles, midagi ei kustutata), käivitab konteineri tühja andmekaustaga ja impordib tõmmise. Seda andmebaasi kasutavad rakendused näevad selle olekut tõmmise võtmise ajast.",
  "dbdump.importConfirmNoVersion": "Kas importida see {engine} tõmmis konteinerisse {container}? BombVault peatab konteineri, lükkab selle andmekausta kõrvale (see jääb alles, midagi ei kustutata), käivitab konteineri tühja andmekaustaga ja impordib tõmmise. Seda andmebaasi kasutavad rakendused näevad selle olekut tõmmise võtmise ajast.",
  "dbdump.importNoVersion": "See tõmmis ei märgi oma andmebaasi versiooni. Import ebaõnnestub, kui server seda lugeda ei suuda.",
  "dbdump.importStops": "one=Importimise ajaks peatab BombVault ka rakenduse {apps} ja käivitab selle pärast uuesti. Kui import ebaõnnestub pärast alustamist, jäävad vanad andmed kõrvale ja rakendus peatatuks.|other=Importimise ajaks peatab BombVault ka need rakendused: {apps}. Pärast käivitatakse need uuesti. Kui import ebaõnnestub pärast alustamist, jäävad vanad andmed kõrvale ja rakendused peatatuks.",
  "dbdump.importDone": "Andmebaas imporditud.",
  "dbdump.importRefused.busy": "Parasjagu käib teine varundus või taaste. Proovi uuesti, kui see on lõppenud.",
  "dbdump.importRefused.notRunning": "Käivita kõigepealt konteiner; import vajab töötavat serverit.",
  "dbdump.importRefused.engineMismatch": "See tõmmis pärineb teist tüüpi andmebaasist kui see, mida konteiner käitab.",
  "dbdump.importRefused.noDataMount": "BombVault ei ulatu selle konteineri andmekaustani ega saa seda turvaliselt kõrvale lükata. Impordi tõmmis käsitsi, nagu taastekomplekt kirjeldab.",
  "dbdump.importRefused.version": "Server töötab versiooniga {server}, tõmmis pärineb versioonist {dump}. Kasuta selleks impordiks tõmmist versiooniga {dump} või uuemat.",
  "dbdump.importRefused.versionSameMajor": "Server töötab versiooniga {server}, tõmmis pärineb versioonist {dump}. MySQL ja MariaDB impordivad tõmmise ainult sellesse põhiversiooni, kust see pärineb, seega kasuta selleks impordiks tõmmisfaili versiooniga {dump}.",
