  "recovery.abTitle": "Impordi Appdata.Backup-pluginast",
  "recovery.abIntro": "Teeb Appdata.Backup-plugina kirjutatud arhiividest vastavate konteinerite taastepunktid, igaühe kuupäevaga, millal plugin selle tegi. Arhiive ainult loetakse, neid ei muudeta ega kustutata kunagi. Iga arhiiv pakitakse lahti hoidla kõrvale, varundatakse ja lahti pakitud koopia kustutatakse jälle, nii et seal peab olema ruumi suurimale arhiivile.",
