  "recovery.dumpOnlyTitle": "Andmebaasid, millest on ainult tõmmis",
  "recovery.dumpOnlyHint": "Neil konteineritel pole failivarundust, ainult andmebaasi tõmmised. Taasta iga üks ja impordi selle tõmmis, enne kui käivitad rakendused, mis seda kasutavad.",
  "recovery.restoreAndImport": "Taasta ja impordi",
  "recovery.dumpOnlySkipped": "one={n} andmebaas, millest on ainult tõmmis, jääb siin välja. Taasta ja impordi see selle oma loendist.|other={n} andmebaasi, millest on ainult tõmmis, jäävad siin välja. Taasta ja impordi need nende oma loendist.",
  "recovery.foreignLatest": "Uusim varundus",
