  "recovery.foreignSubfolderHint": "Taasta sihtkausta ainult selle komplekti märgitud alamkaustad või failid, näiteks üks virn kogu appdata varundusest.",
  "recovery.foreignAppdataDest": "Appdata sihtkoht",
  "recovery.foreignAppdataDestHint": "Kuhu konteineri appdata taastatakse. Jäta tühjaks vaikeväärtuse jaoks. Konteiner, mis varundati poolist, mida sellel serveril pole (nt /mnt/zfs), suunatakse siia, et see õigesti maanduks.",
