  "mcp.stepOAuth": "Lülita sisselogimine sisse",
  "mcp.setupChatGPT": "Ava ChatGPT-s Seaded, Rakendused ja konnektorid ning lülita jaotises Täpsemad seaded sisse arendajarežiim. Vali siis Loo, anna konnektorile nimi, kleebi konnektori URL MCP-serveri URL-iks, vali autentimiseks OAuth, kinnita, et usaldad seda, ja loo see.",
  "mcp.setupClaudeAi": "Ava claude.ai-s Seaded, Konnektorid ja vali Lisa kohandatud konnektor. Anna sellele nimi, kleebi konnektori URL, jäta OAuthi kliendi ID ja saladus tühjaks ning lisa see. Vali siis Ühenda.",
  "mcp.copyConnector": "Kopeeri konnektori URL",
  "mcp.oauthProxyNote": "Teenus kutsub /mcp, /oauth/ ja /.well-known/ oma serveritest, seega peab oma sisselogimisega pöördproksi need teed BombVaultini läbi laskma.",
