  "mcp.certNotForThisAddress": "BombVaulti sertifikaat ei nimeta aadressi {host}, seega abilised keelduvad sellega ühendumast. Lisa aadress sertifikaati ja laadi sertifikaat siis katkete jaoks alla.",
