  "anomaly.settings.title": "Kõrvalekalded",
  "anomaly.settings.hint": "Võrdleb kirje iga varundust selle enda ajalooga ja teatab, mis ei sobi. Töötab pärast iga varundust taustal ega aeglusta ühtki. Enamik kontrolle algab pärast kirje 10 varundust; tõrked, enamiku andmete ülekirjutamine ja peaaegu tühi allikas kontrollitakse kohe algusest. Vaba ruumi jälgitakse kohalike hoidlate ja nende rclone hoidlate puhul, mis sellest teatavad; Unraidi kasutajajaos on see kogu massiivi vaba ruum.",
