  "anomaly.settings.notifyMin": "Saada teavitus, kui",
  "anomaly.settings.notifyHint": "Kasutab jaotises Teavitused seadistatud kanaleid. Iga kirje saab seda muuta jaotises Kõrvalekalded, Jälgimine. Korduvad varundus- ja tõmmisetõrked ning ebaõnnestunud ajastatud taastekontrollid saadavad juba oma sõnumi, seega neid teist korda ei saadeta.",
  "anomaly.settings.notifyMuted": "Praegu ei saadeta midagi: teavitused on välja lülitatud või ühtki kanalit pole seadistatud.",
  "anomaly.settings.openNotifications": "Ava teavituste seaded",
  "anomaly.settings.holdToggle": "Jäta vanad varundused alles, kui allikas järsult kahaneb või kirjutatakse üle",
  "anomaly.settings.holdHint": "Kolm leidu peatavad vanade varunduste kustutamise: allikas, mis on äkki peaaegu tühi, allikas, mis on palju väiksemaks jäänud, ja varundus, mis salvestas suurema osa andmetest uuesti, nagu näeb välja lunavara. Säilitamine kustutaks muidu head vanemad varundused ükshaaval. Kuni selline kõrvalekalle on avatud, jäävad alles ainult selle kirje (või selle andmebaasitõmmise või ZFS-andmestiku) vanad varundused; kõik muu puhastatakse nagu tavaliselt. Jätkamiseks kinnita kõrvalekalle või märgi see oodatuks.",
